+/* Add a zero length item which indicates an expected but missing field */
+proto_item *
+proto_tree_add_missing_field(proto_tree *tree, packet_info *pinfo, int hf, tvbuff_t *tvb,
+                             const gint offset)
+{
+    proto_item *ti = NULL;
